begin;
do $$declare u uuid;u2 uuid;u3 uuid;third uuid;me uuid;reviewer uuid;w uuid;pat uuid;actual_patient uuid;pro uuid;svc uuid;ag uuid;item uuid;actual_item uuid;loc uuid;sup uuid;actual_sup uuid;reg uuid;actual_reg uuid;purchase uuid;line uuid;appt uuid;visit uuid;ord uuid;shift uuid;invoice uuid;s jsonb;d date:=(now() at time zone 'Africa/Cairo')::date;t timestamptz;prefix text:='RX-BRIDGE-'||gen_random_uuid()::text;central uuid;destination uuid;dest uuid;tr uuid;req uuid;blocked boolean:=false;
begin
 if exists(select 1 from clinic_reception.workspaces where mode='live') or (select live_enabled from clinic_reception.settings where id) then raise exception 'Test requires production cutover still disabled';end if;
 select user_id,id into u,me from public.admins where active and user_id is not null and role='super_admin' order by id limit 1;
 select user_id,id into u2,reviewer from public.admins where active and user_id is not null and id<>me order by id limit 1;
 select user_id,id into u3,third from public.admins where active and user_id is not null and id not in(me,reviewer) order by id limit 1;
 if u is null or u2 is null or u3 is null then raise exception 'Two existing active users required';end if;
 select id into central from public.inventory_locations where active order by id limit 1;select id into destination from public.inventory_locations where active and id<>central order by id limit 1;
 perform set_config('request.jwt.claim.sub',u::text,true);execute 'set local role authenticated';
 actual_item:=public.inventory_save_item(null,prefix,'صنف فحص ربط متراجع','اختبار','عبوة',1,0,50,0);
 actual_sup:=public.inventory_save_supplier(null,prefix,'','اختبار يتراجع بالكامل',true);
 actual_reg:=public.clinic_finance_save_register(null,prefix,1000,'both');
 execute 'reset role';
 insert into public.patients(full_name,phone,created_by) values('مريض فحص ربط يتراجع بالكامل','01000000000',me) returning id into actual_patient;
 insert into clinic_reception.workspaces(name,mode,owner_id) values(prefix,'live',me) returning id into w;
 update clinic_reception.settings set live_enabled=true,cutover_at=now();execute 'set local role authenticated';
 perform public.clinic_reception_command(w,'member',jsonb_build_object('admin_id',reviewer,'capabilities',jsonb_build_array('view','review')),gen_random_uuid());
 perform public.clinic_reception_command(w,'member',jsonb_build_object('admin_id',third,'capabilities',jsonb_build_array('view','warehouse')),gen_random_uuid());
 pat:=(public.clinic_reception_command(w,'patient_attach',jsonb_build_object('patient_id',actual_patient),gen_random_uuid())->>'id')::uuid;
 item:=(public.clinic_reception_command(w,'item',jsonb_build_object('code',prefix,'name','مستلزم فحص','unit','عبوة','markup',50),gen_random_uuid())->>'id')::uuid;
 loc:=(public.clinic_reception_command(w,'location',jsonb_build_object('name','مخزن فحص متراجع'),gen_random_uuid())->>'id')::uuid;
 sup:=(public.clinic_reception_command(w,'supplier',jsonb_build_object('name','مورد فحص متراجع'),gen_random_uuid())->>'id')::uuid;
 reg:=(public.clinic_reception_command(w,'register',jsonb_build_object('name','خزينة فحص متراجع','direction','both'),gen_random_uuid())->>'id')::uuid;
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','item','id',item,'external_id',actual_item),gen_random_uuid());
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','location','id',loc,'external_id',central),gen_random_uuid());
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','supplier','id',sup,'external_id',actual_sup),gen_random_uuid());
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','register','id',reg,'external_id',actual_reg),gen_random_uuid());
 pro:=(public.clinic_reception_command(w,'provider',jsonb_build_object('name','طبيب فحص متراجع','department','قسم فحص','branch','اختبار'),gen_random_uuid())->>'id')::uuid;
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','provider','id',pro,'doctor_key',prefix),gen_random_uuid());
 svc:=(public.clinic_reception_command(w,'service',jsonb_build_object('code',prefix,'name','خدمة فحص متراجعة','department','قسم فحص','price',100,'minutes',20,'bom',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',1,'included',true))),gen_random_uuid())->>'id')::uuid;
 ag:=(public.clinic_reception_command(w,'agreement',jsonb_build_object('provider_id',pro,'service_code',prefix,'rate',20,'from',d,'to',d+1,'reference',prefix),gen_random_uuid())->>'id')::uuid;
 purchase:=(public.clinic_reception_command(w,'purchase',jsonb_build_object('supplier_id',sup,'reference',prefix,'lines',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',10,'unit_cost',10))),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);
 perform public.clinic_reception_command(w,'agreement_review',jsonb_build_object('id',ag,'approve',true),gen_random_uuid());
 perform public.clinic_reception_command(w,'purchase_review',jsonb_build_object('id',purchase,'approve',true),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u::text,true);
 s:=public.clinic_reception_snapshot(w,d,d);line:=(s->'purchases'->0->'lines'->0->>'id')::uuid;
 perform public.clinic_reception_command(w,'receive_purchase',jsonb_build_object('id',purchase,'location_id',loc,'lines',jsonb_build_array(jsonb_build_object('line_id',line,'quantity',10,'lot_number',prefix,'expiry_date',d+365))),gen_random_uuid());
 t:=(d::text||' 23:00:00')::timestamp at time zone 'Africa/Cairo';
 perform public.clinic_reception_command(w,'availability',jsonb_build_object('provider_id',pro,'starts_at',t,'ends_at',t+interval '1 hour'),gen_random_uuid());
 appt:=(public.clinic_reception_command(w,'book',jsonb_build_object('patient_id',pat,'provider_id',pro,'service_id',svc,'starts_at',t),gen_random_uuid())->>'id')::uuid;
 visit:=(public.clinic_reception_command(w,'arrive',jsonb_build_object('id',appt,'encounter_type','session'),gen_random_uuid())->>'id')::uuid;
 s:=public.clinic_reception_snapshot(w,d,d);ord:=(s->'orders'->0->>'id')::uuid;
 invoice:=(public.clinic_reception_command(w,'execute',jsonb_build_object('id',ord,'location_id',loc,'materials',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2)),'additional_confirmed',true),gen_random_uuid())->>'id')::uuid;
 shift:=(public.clinic_reception_command(w,'shift_open',jsonb_build_object('register_id',reg),gen_random_uuid())->>'id')::uuid;
 perform public.clinic_reception_command(w,'collect',jsonb_build_object('patient_id',pat,'invoice_id',invoice,'amount',120,'method','cash','shift_id',shift,'reference',prefix),gen_random_uuid());
 perform public.clinic_reception_command(w,'visit_close',jsonb_build_object('id',visit),gen_random_uuid());
 req:=(public.clinic_reception_command(w,'request',jsonb_build_object('kind','doctor_payout','subject_id',pro,'amount',20,'method','bank','reference',prefix||'-DOC','reason','فحص تسوية أتعاب مدفوعة','evidence',prefix),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'request_review',jsonb_build_object('id',req,'approve',true,'note','فحص يتراجع بالكامل'),gen_random_uuid());perform set_config('request.jwt.claim.sub',u::text,true);
 req:=(public.clinic_reception_command(w,'request',jsonb_build_object('kind','credit_note','subject_id',invoice,'amount',15,'scope','materials','reason','تصحيح مستلزم إضافي فقط','evidence',prefix),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'request_review',jsonb_build_object('id',req,'approve',true,'note','فحص يتراجع بالكامل'),gen_random_uuid());perform set_config('request.jwt.claim.sub',u::text,true);
 req:=(public.clinic_reception_command(w,'request',jsonb_build_object('kind','credit_note','subject_id',invoice,'amount',10,'scope','service','reason','تصحيح حصة من الخدمة','evidence',prefix),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'request_review',jsonb_build_object('id',req,'approve',true,'note','فحص يتراجع بالكامل'),gen_random_uuid());perform set_config('request.jwt.claim.sub',u::text,true);
 dest:=(public.clinic_reception_command(w,'location',jsonb_build_object('name','مخزن استقبال فحص متراجع'),gen_random_uuid())->>'id')::uuid;
 perform public.clinic_reception_command(w,'master_link',jsonb_build_object('kind','location','id',dest,'external_id',destination),gen_random_uuid());
 tr:=(public.clinic_reception_command(w,'transfer_request',jsonb_build_object('item_id',item,'source_id',loc,'destination_id',dest,'quantity',2,'reason','تحويل فحص متراجع'),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'transfer_review',jsonb_build_object('id',tr,'stage','manager','approve',true),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u3::text,true);perform public.clinic_reception_command(w,'transfer_review',jsonb_build_object('id',tr,'stage','warehouse','approve',true),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.clinic_reception_command(w,'transfer_dispatch',jsonb_build_object('id',tr),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u3::text,true);perform public.clinic_reception_command(w,'transfer_receive',jsonb_build_object('id',tr,'quantity',1,'reason','قطعة لم تصل — فحص متراجع'),gen_random_uuid());
 perform set_config('request.jwt.claim.sub',u::text,true);req:=(public.clinic_reception_command(w,'request',jsonb_build_object('kind','transfer_loss','subject_id',tr,'amount',10,'reason','محضر فقد تجريبي متراجع','evidence',prefix),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'request_review',jsonb_build_object('id',req,'approve',true,'note','خسارة دون تحميل موظف — فحص يتراجع'),gen_random_uuid());perform set_config('request.jwt.claim.sub',u::text,true);
 req:=(public.clinic_reception_command(w,'marketing_spend',jsonb_build_object('ad_id',prefix,'reference',prefix,'lines',jsonb_build_array(jsonb_build_object('day',d,'amount',5))),gen_random_uuid())->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',u2::text,true);perform public.clinic_reception_command(w,'marketing_review',jsonb_build_object('id',req,'approve',true,'note','مرجع مصروف تحليلي متراجع'),gen_random_uuid());perform set_config('request.jwt.claim.sub',u::text,true);perform public.clinic_reception_marketing(w,d,d);
 perform public.clinic_reception_finance_overview(d,d);perform public.clinic_reception_indicator_export(w,d,d);perform public.clinic_reception_masters(w);
 execute 'reset role';
 if (select archive_visit_id is null from clinic_reception.visits where id=visit) then raise exception 'Missing unified visit';end if;
 if public.inventory_location_balance(central,actual_item,null,true)<>6 or public.inventory_location_balance(destination,actual_item,null,true)<>1 then raise exception 'Wrong physical inventory';end if;
 if clinic_finance.supplier_balance(actual_sup)<>100 or clinic_finance.doctor_balance(prefix)<>-2 then raise exception 'Unified balance mismatch';end if;
 if clinic_reception.due(invoice)<>0 or clinic_reception.balance(w,'2150','patient_id',pat::text)<>-30 then raise exception 'Wrong allocation/credit';end if;
 if exists(select 1 from clinic_reception.journal where workspace_id=w and finance_entry_id is null) then raise exception 'Unposted event';end if;
 if exists(select 1 from clinic_finance.entries where source in ('inventory_usage','inventory_waste','inventory_count') and source_id in(select inventory_movement_id from clinic_reception.movements where workspace_id=w)) then raise exception 'Stock posted twice';end if;
 if exists(select 1 from clinic_finance.entries e join clinic_finance.lines l on l.entry_id=e.id where e.id in(select finance_entry_id from clinic_reception.journal where workspace_id=w) group by e.id having sum(l.debit)<>sum(l.credit)) then raise exception 'Unbalanced live journal';end if;
end $$;
rollback;
select jsonb_build_object('test','reception final controls production rollback passed','live_enabled',(select live_enabled from clinic_reception.settings where id),'live_workspaces',(select count(*) from clinic_reception.workspaces where mode='live'),'anonymous_delivery_blocked',not has_function_privilege('anon','public.clinic_reception_message_claim(integer)','execute'),'authenticated_delivery_blocked',not has_function_privilege('authenticated','public.clinic_reception_message_claim(integer)','execute'));
